set -eu
export DEBIAN_FRONTEND=noninteractive
mkdir -p /root/sugarscape/thaler-native-timing-002
cd /root/sugarscape/thaler-native-timing-002
exec > >(tee -a bootstrap.log) 2>&1
touch versions.txt source-status.txt
trap 'rc=$?; printf "%s\n" "$rc" > exit-code.txt; tar -czf /root/sugarscape/thaler-native-timing-evidence-002.tar.gz --exclude=source --exclude="checkpoint-*" .; exit "$rc"' EXIT
printf '%s' '' | base64 -d > run_timing.py
printf '%s' '' | base64 -d > protocol.json
printf '%s' '' | base64 -d > revision-fidelity.json
printf '%s' '' | base64 -d > stack-global-config.yaml
timeout 600 bash -c 'apt-get update -qq && apt-get install -y -qq haskell-stack git curl ca-certificates gcc make libgmp-dev libtinfo5 freeglut3-dev python3'
mkdir -p /root/.stack
cp stack-global-config.yaml /root/.stack/config.yaml
stack --version > versions.txt
uname -a >> versions.txt
lscpu >> versions.txt
printf '%s  %s\n' '69166a06218a0177fc9da80e1e82b9e759843041fbb36cd515c2647e76538ab0' '/root/sugarscape/source-f5851488.tar.gz' | sha256sum -c -
mkdir source
tar -xzf /root/sugarscape/source-f5851488.tar.gz -C source
printf '%s\n' 'git archive f5851488bf2369e2bbdc3f2499ed69c142de9fec; file pins verified by runner' > source-status.txt
timeout --signal=TERM --kill-after=30 42000 python3 run_timing.py source results
sha256sum /root/sugarscape/source-f5851488.tar.gz >> source-status.txt
